# Find which browser profiles are hogging disk (PowerShell)
$paths = @("$env:LOCALAPPDATA\Google\Chrome\User Data", "$env:LOCALAPPDATA\Microsoft\Edge\User Data", "$env:APPDATA\Mozilla\Firefox\Profiles")
foreach ($p in $paths) { if (Test-Path $p) { $gb = [math]::Round((Get-ChildItem $p -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum/1GB,2); Write-Output "$gb GB  $p" } }
